    if len(argv) == 5 and argv[1] == "benchmark_data":
        return _cmd_benchmarkdata(argv[2], argv[3], argv[4])
    if len(argv) == 5 and argv[1] == "predictdata":
        return _cmd_predictdata(argv[2], argv[3], argv[4])
    if len(argv) == 4 and argv[1] == "gradcheck":
